const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const proposalId = String(payload.proposalId || payload.id || '').trim();
const recipientEmail = String(payload.email || payload.recipientEmail || '').trim().toLowerCase();
const companyName = String(payload.companyName || payload.company || 'your team').trim();
const recipientName = String(payload.recipientName || payload.contactName || '').trim();
const proposalStatus = String(payload.proposalStatus || payload.status || 'sent').toLowerCase();

const isSuppressed = Boolean(payload.suppressed || payload.optedOut || payload.unsubscribed);
const isTerminalStatus = ['won', 'lost', 'cancelled', 'signed'].includes(proposalStatus);

if (isSuppressed || isTerminalStatus) {
  return [{
    json: {
      eventId: item.eventId,
      status: 'processed',
      followup: {
        proposalId,
        action: 'halted',
        reason: isSuppressed ? 'Contact is opted out or suppressed' : ('Proposal is already in terminal status: ' + proposalStatus),
        eligible: false
      }
    }
  }];
}

return [{
  json: {
    eventId: item.eventId,
    proposalId,
    recipientEmail,
    companyName,
    recipientName,
    proposalStatus,
    attempts: Number(payload.attempts || payload.touchCount || 0),
    lastContactedAt: payload.lastContactedAt || null,
    packageName: String(payload.packageName || 'Technical Proposal').trim()
  }
}];

const item = $input.first().json;
if (item.followup && !item.followup.eligible) {
  return [{ json: item }];
}

const attempts = item.attempts;
const MAX_TOUCHES = 3;

if (attempts >= MAX_TOUCHES) {
  return [{
    json: {
      eventId: item.eventId,
      status: 'processed',
      followup: {
        proposalId: item.proposalId,
        action: 'sequence_completed',
        reason: 'Maximum follow-up touches (' + MAX_TOUCHES + ') reached. File moved to passive nurture.',
        eligible: false
      }
    }
  }];
}

if (item.lastContactedAt) {
  const lastTime = new Date(item.lastContactedAt).getTime();
  const elapsedHours = (Date.now() - lastTime) / (1000 * 60 * 60);
  if (elapsedHours < 48) {
    return [{
      json: {
        eventId: item.eventId,
        status: 'processed',
        followup: {
          proposalId: item.proposalId,
          action: 'interval_waiting',
          reason: 'Minimum 48 hours required between touches (elapsed: ' + Math.round(elapsedHours) + 'h).',
          eligible: false
        }
      }
    }];
  }
}

const nextTouchNumber = attempts + 1;

return [{
  json: {
    ...item,
    nextTouchNumber
  }
}];

const item = $input.first().json;
if (item.followup) {
  return [{ json: item }];
}

const touch = item.nextTouchNumber;
const recipient = item.recipientName ? item.recipientName.split(' ')[0] : 'there';
const company = item.companyName;
const pkg = item.packageName;

let subject = '';
let body = '';

if (touch === 1) {
  subject = 'Following up on ' + company + ' technical proposal';
  body = [
    'Hi ' + recipient + ',',
    '',
    'Checking in to ensure you received the ' + pkg + ' proposal we prepared for ' + company + '.',
    '',
    'If you or your technical team have any questions on the architecture blueprint or milestone milestones, I would be glad to address them.',
    '',
    'Best regards,',
    'Vikash Saravanan',
    'Lead System Engineer | Logic Intelligence Technologies'
  ].join('\n');
} else if (touch === 2) {
  subject = 'Architecture walkthrough & preview for ' + company;
  body = [
    'Hi ' + recipient + ',',
    '',
    'Following up on our earlier note regarding ' + company + "'s project proposal.",
    '',
    'We frequently build interactive component previews during Phase 1 to de-risk delivery. If helpful, I can walk you through a brief 15-minute live preview of the proposed system architecture.',
    '',
    'Let me know if you would like me to set that up.',
    '',
    'Best regards,',
    'Vikash Saravanan',
    'Lead System Engineer | Logic Intelligence Technologies'
  ].join('\n');
} else {
  subject = 'Permission to close file / next steps for ' + company;
  body = [
    'Hi ' + recipient + ',',
    '',
    'I know priorities shift rapidly, so I will pause our active follow-ups regarding the ' + pkg + ' proposal to keep your inbox clear.',
    '',
    'We keep your architecture notes on file, so whenever you are ready to revisit or take on new development, feel free to reach out.',
    '',
    'Wishing you and the ' + company + ' team continued success.',
    '',
    'Warm regards,',
    'Vikash Saravanan',
    'Lead System Engineer | Logic Intelligence Technologies'
  ].join('\n');
}

return [{
  json: {
    ...item,
    draftMessage: {
      touchNumber: touch,
      subject,
      body,
      generatedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
if (item.followup) {
  return [{
    json: {
      eventId: item.eventId,
      status: 'processed',
      followup: item.followup
    }
  }];
}

const crypto = require('crypto');
const queueId = crypto.randomUUID();

const queuedItem = {
  queueId,
  proposalId: item.proposalId,
  recipientEmail: item.recipientEmail,
  companyName: item.companyName,
  touchNumber: item.nextTouchNumber,
  subject: item.draftMessage.subject,
  body: item.draftMessage.body,
  status: 'queued_for_approval',
  action: 'touch_queued',
  createdAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'processed',
    followup: queuedItem
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: { followup: item.json.followup }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
